import {ANIMATIONS,animationById,animationFor,outcomeFor,presentationFor,advancePresentation} from './animation-manifest.mjs';
import {castFor,defaultCast,character,validateCharacter,SKINS,HAIRS,CLOTHES} from './characters.mjs';
import {IncidentAnimationPlayer} from './incident-animation-player.mjs';
import * as G from './goals.mjs';
import * as D from './director.mjs';

export function createAnimationUI(ctx){
 const {getState:S,tr,tx,esc,cash,button:b,openModal,closeModal,save,render,navigate,select,field,formValues}=ctx;
 let player=null,activeSpec=null,showcase=false,previewAsset=null,completion=null;
 const J=()=>D.activeJourney(S());
 function dispose(){player?.destroy();player=null;activeSpec=null;}
 function cast(){return castFor(S());}
 const studioBar=()=>`<div class="scene-studio-bar">${b(tr('My story characters','我的故事角色'),'ani-characters','light smallbtn')}${b(tr('Animation studio','动画工作室'),'ani-library','light smallbtn')}</div>`;
 function limits(){const g=G.currentGoal(S());if(!g)return '';return `<div class="scene-limit-strip"><span>${tr('Approved monthly limit','已批准每月限额')}: <strong>${cash(g.comfortableMonthly,g.currency)}</strong></span><span>${tr('Available main-goal capacity','主目标可用能力')}: <strong>${cash(G.monthLimit(S(),g),g.currency)}</strong></span><span>${tr('Goal duration','目标时长')}: <strong>${g.months} ${tr('months','个月')}</strong></span><span>${tr('Goal remaining','剩余目标')}: <strong>${cash(G.goalProgress(S(),g).remaining,g.currency)}</strong></span><span>${tr('Savings Day','储蓄日')}: <strong>8</strong></span></div>`;}
 function slot(asset,{mode='opening',optionTitle='',onFinish=()=>{},twins=false,babies=0}={}){activeSpec={asset,cast:cast(),language:S().language,mode,optionTitle,twins,babies,onFinish,onPreference:preferences=>{G.ensureGame(S()).animationPreferences={...preferences};save();},preferences:G.ensureGame(S()).animationPreferences||{}};return '<div id="incident-animation-slot"></div>';}
 function mount(){const el=document.querySelector('#incident-animation-slot');if(!el||!activeSpec)return;player?.destroy();player=new IncidentAnimationPlayer(el,activeSpec);}
 function incident(s,i,financialContent){const a=animationFor(s,i),p=presentationFor(i),phase=i.decision?'financial':p.phase;const step=({opening:0,dialogue:1,choices:2,outcome:3,financial:4})[phase];
  const steps=[tr('Scene','场景'),tr('Dialogue','对话'),tr('Choice','选择'),tr('Outcome','结果'),tr('Savings','储蓄')];
  let content='',asset=a,mode='ambient',onFinish=()=>{},title='';
  const complete=event=>{const current=J()?.v2.current;if(current?.id!==i.id)return;advancePresentation(current,event);save();render();};
  if(phase==='opening'){mode='opening';onFinish=()=>complete('opening-finished');content=`<div class="scene-finance-lock">${tr('First, step into the scene. Dialogue, choices and itemized expenses follow. Skipping is always available.','先走进场景，再阅读对白、选择及开支明细。随时可以跳过。')}</div>`;}
  if(phase==='dialogue')content=`<section class="scene-dialogue-card"><span class="scene-choice-label">${tr('A moment before the decision','决定前的一刻')}</span><blockquote>${tx(i.dialogue)}</blockquote><p class="small muted">${tx(i.intro)}</p>${s.story==='baby'?`<p class="small muted">${tr('This is a fictional family, not a medical timeline. The saved 1% twins branch is a game mechanic.','这是虚构家庭，并非医疗时间表。已保存的1%双胎分支属于游戏机制。')}</p>`:''}<div class="mt12">${b(tr('Let’s see the choices','看看有哪些选择'),'ani-continue')}</div></section>`;
  if(phase==='choices')content=`<div class="section-head"><h3>${tr('How will you respond?','你会如何应对？')}</h3></div><div class="decisions">${i.options.map(o=>`<button class="decision" data-action="v2-choice:${i.id}:${o.id}" ${G.currentGoal(S()).paused?'disabled':''}><span class="choice-circle"></span><span><strong>${tx(o.title)}</strong><small>${tx(o.description)}</small></span></button>`).join('')}</div><p class="tiny muted mt12">${tr('Your chosen response plays next. You can review its itemized costs and savings schedule before saving the decision.','接着播放所选应对，你可以在保存决定前审阅开支明细和储蓄计划。')}</p>`;
  if(phase==='outcome'){const option=i.options.find(o=>o.id===p.optionId);asset=outcomeFor(a,p.optionId);mode='outcome';title=option?tx(option.title):'';onFinish=()=>complete('outcome-finished');content=`<div class="scene-finance-lock">${tr('Your response is unfolding. The financial reveal is next. No savings have been credited.','你的应对正在展开，随后揭示财务明细，目前尚未计入任何储蓄。')}</div>`;}
  if(phase==='financial'&&!i.decision){const option=i.options.find(o=>o.id===p.optionId);if(!option){advancePresentation(i,'choose',i.options[0].id);p.phase='choices';return incident(s,i,financialContent);}asset=outcomeFor(a,p.optionId);title=tx(option.title);content=`<section class="scene-dialogue-card"><div class="scene-choice-label">${tr('The financial reveal','财务明细揭晓')}</div><h3 class="mt12">${tx(option.title)}</h3><p class="small muted mt12">${tr('The scene is complete. Review the country-specific items and choose an affordable savings share. Your decision is committed only when you save the plan.','场景已结束。审阅各国独立项目并选择可负担储蓄比例，保存计划后才正式记录决定。')}</p><div class="form-actions">${b(tr('Review itemized costs & savings','审阅开支明细与储蓄'),'ani-plan')}${b(tr('Choose another response','选择其他应对'),'ani-rechoose','light')}</div></section>`;}
  if(i.decision){asset=outcomeFor(a,i.decision.id);content=financialContent();}
  return `<section class="cinematic-section"><div class="cinematic-header"><div><div class="scene-chapter">${tr('An animated storybook','动画故事书')}</div><h2>${phase==='outcome'?tr('Your choice, brought to life','让你的选择活起来'):tr('A page in your virtual life','虚拟人生中的一页')}</h2></div>${b(tr('Characters','角色'),'ani-characters','light smallbtn')}</div><div class="stage-steps" aria-label="${tr('Incident stages','事件阶段')}">${steps.map((label,n)=>`<span class="${n===step?'current':''}" ${n===step?'aria-current="step"':''}>${n+1} · ${label}</span>`).join('')}</div>${slot(asset,{mode,optionTitle:title,onFinish,twins:!!s.v2.flags.twins,babies:s.v2.assets.family?.babies||0})}${limits()}${content}</section>`;
 }
 function library(){showcase=true;return `<div class="scene-chapter">${tr('The animation studio','动画工作室')}</div><h1>${tr('Little scenes. A life in motion.','小小场景，让生活动起来。')}</h1><p class="small muted mt12">${tr('Original painted settings and reusable layered characters. These previews are fictional and do not affect your savings or reveal your next incident.','原创手绘场景与可复用分层角色。这些虚构预览不会影响储蓄，也不揭示下一个事件。')}</p>${studioBar()}<div class="animation-library-note">${tr(`Available now: ${ANIMATIONS.length} SVG scene compositions, including the 7-second positive-test sequence. The other stories use reusable stage templates. No pre-rendered movie or voice track is claimed.`,`目前提供${ANIMATIONS.length}个SVG场景组合，包括7秒阳性测试动画。其他故事使用复用舞台模板，目前没有预渲染影片或配音。`)}</div>${b(tr('Back to my story','返回我的故事'),'ani-back','secondary smallbtn')}<div class="animation-library mt">${ANIMATIONS.map(a=>`<button class="animation-tile" data-action="ani-preview:${a.id}"><span class="eyebrow">${a.storyId} · ${(a.durationMs/1000).toFixed(1)}s · SVG</span><h3>${esc(a.title)}</h3><p>${esc(a.description)}</p><span class="tiny">${tr('Play with my characters','用我的角色播放')} →</span></button>`).join('')}</div>`;}
 function preview(id){previewAsset=animationById(id);showcase=true;navigate('story');}
 function previewPage(){return `<div class="cinematic-header"><div><div class="scene-chapter">${tr('Animation preview · no financial effects','动画预览 · 不影响财务')}</div><h2>${esc(previewAsset.title)}</h2></div>${b(tr('Back to studio','返回工作室'),'ani-library','light smallbtn')}</div>${slot(previewAsset,{twins:previewAsset.id==='pregnancy_twins_reveal',onFinish:()=>{}})}<p class="small muted mt12">${tr('Playback and replay change presentation only. Skip never unlocks a savings checkpoint.','播放和重播只影响演出，跳过动画不会解锁储蓄点。')}</p>${studioBar()}`;}
 const previewCast=()=>`<div class="character-preview"><svg viewBox="0 0 500 230" role="img" aria-label="${tr('Your player and partner','你的主角和伴侣')}"><rect width="500" height="230" fill="#e7ddc9"/>${character(cast().player,{x:170,y:210,scale:1})}${character(cast().partner,{id:'partner',x:330,y:210,scale:1})}</svg></div>`;
 function characters(){const c=cast();openModal(tr('The people in your story','故事中的人物'),`${previewCast()}<p class="small muted mt12">${tr('One consistent model follows you through every scene. Appearance is independent of the character’s role or story outcomes.','同一角色模型贯穿每个场景，外观与故事角色或结果无关。')}</p><form id="ani-character-form">${['player','partner'].map(w=>`<section class="character-editor"><h3>${w==='player'?tr('You, in the story','故事中的你'):tr('Your virtual partner','你的虚拟伴侣')}</h3><div class="form-grid">${field(tr('Name','名字'),w+'Name',c[w].name,'text','','maxlength="40" required')}${select(tr('Hair style','发型'),w+'Hairstyle',c[w].hairstyle,[['wave',tr('Soft wave','柔和波浪')],['crop',tr('Short crop','短发')],['bob',tr('Bob','波波头')],['long',tr('Long','长发')]])}${select(tr('Skin tone','肤色'),w+'Skin',c[w].skin,SKINS.map((v,n)=>[v,`${tr('Tone','色调')} ${n+1}`]))}${select(tr('Hair color','发色'),w+'Hair',c[w].hair,HAIRS.map((v,n)=>[v,[tr('Soft black','柔黑'),tr('Dark brown','深棕'),tr('Chestnut','栗色'),tr('Silver brown','银棕'),tr('Charcoal','炭灰')][n]]))}${select(tr('Clothing','服装'),w+'Clothing',c[w].clothing,CLOTHES.map((v,n)=>[v,[tr('Sage','鼠尾草绿'),tr('Terracotta','赤陶'),tr('Burgundy','酒红'),tr('Forest','森林绿'),tr('Warm brown','暖棕')][n]]))}${select(tr('Gender presentation','性别表达'),w+'Presentation',c[w].presentation,[['androgynous',tr('Androgynous','中性')],['feminine',tr('Feminine','女性化')],['masculine',tr('Masculine','男性化')]])}${select(tr('Accessory','配饰'),w+'Accessory',c[w].accessory,[['none',tr('None','无')],['glasses',tr('Glasses','眼镜')],['earrings',tr('Earrings','耳环')]])}</div></section>`).join('')}<div class="form-error error" role="alert"></div><div class="form-actions"><button class="btn" type="submit">${tr('Save my characters','保存我的角色')}</button></div></form>`);}
 async function action(a){const [kind,id]=a.split(':');if(!kind.startsWith('ani-'))return false;if(kind==='ani-characters')characters();if(kind==='ani-library'){previewAsset=null;showcase=true;closeModal();navigate('story');}if(kind==='ani-back'){showcase=false;previewAsset=null;navigate('story');}if(kind==='ani-preview')preview(id);if(kind==='ani-continue'){const i=J()?.v2.current;if(i)advancePresentation(i,'continue');save();render();}if(kind==='ani-rechoose'){const i=J()?.v2.current;if(i&&!i.decision){i.presentation={...presentationFor(i),phase:'choices'};save();render();}}return true;}
 async function submit(f){if(f.id!=='ani-character-form')return false;const d=formValues(f),c=defaultCast();for(const w of ['player','partner']){c[w]={name:d[w+'Name'].trim(),skin:d[w+'Skin'],hair:d[w+'Hair'],hairstyle:d[w+'Hairstyle'],clothing:d[w+'Clothing'],presentation:d[w+'Presentation'],accessory:d[w+'Accessory']};if(!validateCharacter(c[w]))throw Error('Please choose valid character details and a name of 1–40 characters.');}G.ensureGame(S()).characters=c;save();closeModal();render();return true;}
 return {action,submit,dispose,mount,incident,studioBar,playCompletion(s,i){completion={s,i};showcase=false;previewAsset=null;},clearStudio(){showcase=false;previewAsset=null;completion=null;},renderStudio(){if(completion){const {s,i}=completion;return `<div class="cinematic-header"><div><div class="scene-chapter">${tr('Checkpoint complete','储蓄点已完成')}</div><h2>${tx(i.title)}</h2></div></div>${slot(animationById('milestone_completion'),{mode:'completion',twins:!!s.v2.flags.twins,onFinish:()=>{completion=null;render();}})}${limits()}`;}return showcase?previewAsset?previewPage():library():null;}};
}
